{"command":"cat <<'EOF' > tui_proto.go
package main

import (
	"fmt"
	"os"
	"os/exec"
	"os/signal"
	"syscall"
)

func main() {
	// Set raw mode
	cbterm := exec.Command("stty", "raw", "-echo")
	cbterm.Stdin = os.Stdin
	cbterm.Run()
	defer func() {
		cbterm := exec.Command("stty", "-raw", "echo")
		cbterm.Stdin = os.Stdin
		cbterm.Run()
	}()

	// Handle signals
	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, os.Interrupt, syscall.SIGTERM)
	go func() {
		<-sigChan
		// Clean up and exit
		fmt.Print("\033[?25h") // show cursor
		os.Exit(0)
	}()

	fmt.Print("\033[?25l") // hide cursor
	fmt.Print("\033[H\033[2J") // clear screen

	// Draw something
	fmt.Print("\033[1;1HStatus: workspace -> master")
	fmt.Print("\033[2;1HFiles: ?? executable")
	fmt.Print("\033[10;1HPress 'q' to quit")

	// Input loop
	buf := make([]byte, 1)
	for {
		os.Stdin.Read(buf)
		if buf[0] == 'q' {
			break
		}
	}
	fmt.Print("\033[?25h") // show cursor
	fmt.Print("\033[H\033[2J") // clear screen
}
EOF
go build -o tui_proto tui_proto.go
# I can't really test it interactively here, but I can check if it compiles.
"}

