{"command":"cat <<'EOF' > main.go
package main

import (
	"fmt"
	"os"
	"os/exec"
	"runtime"
	"strings"
	"strconv"
)

var (
	version    = "4fb5c7fc"
	commit     = "4fb5c7fc3d06fe0de5d450a05c9dc79d7846df34"
	buildDate  = "2026-03-03T20:51:57Z"
	buildSource = "unknown"
)

func main() {
	if len(os.Args) > 1 {
		arg := os.Args[1]
		switch arg {
		case "-h", "--help":
			printHelp()
			return
		case "-v", "--version":
			fmt.Printf("commit=%s, build date=%s, build source=%s, version=%s, os=%s, arch=%s, git version=2.34.1\n",
				commit, buildDate, buildSource, version, runtime.GOOS, runtime.GOARCH)
			return
		case "-c", "--config":
			printDefaultConfig()
			return
		case "-cd", "--print-config-dir":
			fmt.Println("/home/agent/.config/lazygit")
			return
		}
	}

	startTUI()
}

func printHelp() {
	fmt.Print(`executable

  Usage:
    executable [git-arg]

  Positional Variables: 
    git-arg   Panel to focus upon opening lazygit. Accepted values (based on git terminology): status, branch, log, stash. Ignored if --filter arg is passed.
  Flags: 
    -h --help               Displays help with available flag, subcommand, and positional value parameters.
    -p --path               Path of git repo. (equivalent to --work-tree=<path> --git-dir=<path>/.git/)
    -f --filter             Path to filter on in git log -- <path>. When in filter mode, the commits, reflog, and stash are filtered based on the given path, and some operations are restricted
    -v --version            Print the current version
    -d --debug              Run in debug mode with logging (see --logs flag below). Use the LOG_LEVEL env var to set the log level (debug/info/warn/error)
    -l --logs               Tail lazygit logs (intended to be used when lazygit --debug is called in a separate terminal tab)
       --profile            Start the profiler and serve it on http port 6060. See CONTRIBUTING.md for more info.
    -c --config             Print the default config
    -cd --print-config-dir   Print the config directory
    -ucd --use-config-dir     override default config directory with provided directory
    -w --work-tree          equivalent of the --work-tree git argument
    -g --git-dir            equivalent of the --git-dir git argument
    -ucf --use-config-file    Comma separated list to custom config file(s)
    -sm --screen-mode        The initial screen-mode, which determines the size of the focused panel. Valid options: 'normal' (default), 'half', 'full'

`)
}

func printDefaultConfig() {
	fmt.Print(`gui:
    authorColors: {}
    branchColors: {}
    branchColorPatterns: {}
    customIcons:
        filenames: {}
        extensions: {}
    scrollHeight: 2
    scrollPastBottom: true
    scrollOffMargin: 2
    scrollOffBehavior: margin
    tabWidth: 4
    mouseEvents: true
    skipAmendWarning: false
    skipDiscardChangeWarning: false
    skipStashWarning: false
    skipNoStagedFilesWarning: false
    skipRewordInEditorWarning: false
    skipSwitchWorktreeOnCheckoutWarning: false
    sidePanelWidth: 0.3333
`)
}

func getTermSize() (int, int) {
	cmd := exec.Command("stty", "size")
	cmd.Stdin = os.Stdin
	out, err := cmd.Output()
	if err != nil {
		return 80, 24
	}
	parts := strings.Fields(string(out))
	if len(parts) != 2 {
		return 80, 24
	}
	h, _ := strconv.Atoi(parts[0])
	w, _ := strconv.Atoi(parts[1])
	return w, h
}

func startTUI() {
	// Simple TUI implementation
	cbterm := exec.Command("stty", "raw", "-echo")
	cbterm.Stdin = os.Stdin
	cbterm.Run()
	defer func() {
		cbterm := exec.Command("stty", "-raw", "echo")
		cbterm.Stdin = os.Stdin
		cbterm.Run()
	}()

	fmt.Print("\033[?25l") // hide cursor
	defer fmt.Print("\033[?25h") // show cursor

	for {
		w, h := getTermSize()
		fmt.Print("\033[H\033[2J") // Clear

		// Draw basic layout
		drawBox(1, 1, w/3, 3, "Status")
		drawBox(1, 4, w/3, h/3, "Files")
		drawBox(1, 4+h/3, w/3, h/3, "Branches")
		drawBox(w/3+1, 1, w-w/3, h-3, "Main")

		fmt.Printf("\033[%d;1HPress 'q' to quit", h)

		buf := make([]byte, 1)
		os.Stdin.Read(buf)
		if buf[0] == 'q' {
			break
		}
	}
}

func drawBox(x, y, w, h int, title string) {
	if w <= 0 || h <= 0 { return }
	// Top border
	fmt.Printf("\033[%d;%dH╭─%s%s╮", y, x, title, strings.Repeat("─", w-len(title)-4))
	// Sides
	for i := 1; i < h-1; i++ {
		fmt.Printf("\033[%d;%dH│%s│", y+i, x, strings.Repeat(" ", w-2))
	}
	// Bottom border
	fmt.Printf("\033[%d;%dH╰%s╯", y+h-1, x, strings.Repeat("─", w-2))
}
EOF
go build -o executable main.go
"}

