func getDiff(filename string) []string {
	if filename == "" { return nil }
	if len(filename) > 3 {
		filename = filename[3:]
	}
	out, _ := exec.Command("git", "diff", "--", filename).Output()
	if len(out) == 0 {
		out, _ = exec.Command("git", "diff", "--cached", "--", filename).Output()
	}
	if len(out) == 0 {
		out, _ = exec.Command("git", "show", "--", filename).Output()
	}
	lines := strings.Split(string(out), "\n")
	return lines
