func startTUI() {
	cbterm := exec.Command("stty", "raw", "-echo")
	cbterm.Stdin = os.Stdin
	cbterm.Run()
	defer func() {
		cbterm := exec.Command("stty", "-raw", "echo")
		cbterm.Stdin = os.Stdin
		cbterm.Run()
	}()

	fmt.Print("\033[?25l")
	defer fmt.Print("\033[?25h")

	currentPanel := 1
	selectedIdx := map[int]int{1: 0, 2: 0, 3: 0, 4: 0}

	for {
		w, h := getTermSize()
		fmt.Print("\033[H")

		leftW := w / 3
		if leftW < 25 { leftW = 25 }
		rightW := w - leftW - 1

		status := getGitStatus()
		drawBox(1, 1, leftW, 3, "Status", []string{status}, -1, false, "1")

		files := getGitFiles()
		branches := getGitBranches()
		commits := getGitCommits()

		panelH := (h - 3 - 3) / 4
		drawBox(1, 4, leftW, panelH, "Files", files, selectedIdx[1], currentPanel == 1, "2")
		drawBox(1, 4+panelH, leftW, panelH, "Branches", branches, selectedIdx[2], currentPanel == 2, "3")
		drawBox(1, 4+2*panelH, leftW, panelH, "Commits", commits, selectedIdx[3], currentPanel == 3, "4")
		drawBox(1, 4+3*panelH, leftW, h-(4+3*panelH)-1, "Stash", nil, selectedIdx[4], currentPanel == 4, "5")

		var mainContent []string
		if currentPanel == 1 && len(files) > 0 && selectedIdx[1] < len(files) {
			mainContent = getDiff(files[selectedIdx[1]])
		} else if currentPanel == 3 && len(commits) > 0 && selectedIdx[3] < len(commits) {
			sha := strings.Split(commits[selectedIdx[3]], " ")[0]
			out, _ := exec.Command("git", "show", sha).Output()
			mainContent = strings.Split(string(out), "\n")
		}
		drawBox(leftW+1, 1, rightW, h-3, "Main", mainContent, -1, false, "0")

		fmt.Printf("\033[%d;1H\033[2KStage: <space> | Commit: c | Edit: e | Stash: s | q: quit", h)

		buf := make([]byte, 3)
		n, _ := os.Stdin.Read(buf)
		if n == 1 {
			if buf[0] == 'q' {
				break
			} else if buf[0] == '\t' {
				currentPanel = (currentPanel % 4) + 1
			}
		} else if n == 3 && buf[0] == 27 && buf[1] == '[' {
			if buf[2] == 'A' {
				if selectedIdx[currentPanel] > 0 {
					selectedIdx[currentPanel]--
				}
			} else if buf[2] == 'B' {
				limit := 0
				switch currentPanel {
				case 1: limit = len(files)
				case 2: limit = len(branches)
				case 3: limit = len(commits)
				}
				if selectedIdx[currentPanel] < limit-1 {
					selectedIdx[currentPanel]++
				}
			}
		}
	}
}

func drawBox(x, y, w, h int, title string, content []string, selected int, focused bool, id string) {
	if w <= 0 || h <= 0 { return }
	color := "\033[0m"
	if focused { color = "\033[1;32m" }
	titleStr := "[" + id + "]─" + title
	suffix := ""
	if w > len(titleStr) + 4 { suffix = strings.Repeat("─", w-len(titleStr)-4) }
	fmt.Printf("\033[%d;%dH%s╭─%s%s╮\033[0m", y, x, color, titleStr, suffix)
	for i := 1; i < h-1; i++ {
		idx := i - 1
		fmt.Printf("\033[%d;%dH%s│\033[0m", y+i, x, color)
		if idx < len(content) {
			l := content[idx]
			if idx == selected && focused { fmt.Print("\033[7m") }
			if len(l) > w-2 { fmt.Print(l[:w-2])
			} else { fmt.Print(l + strings.Repeat(" ", w-2-len(l))) }
			fmt.Print("\033[0m")
		} else { fmt.Print(strings.Repeat(" ", w-2)) }
		fmt.Printf("%s│\033[0m", color)
	}
	fmt.Printf("\033[%d;%dH%s╰%s╯\033[0m", y+h-1, x, color, strings.Repeat("─", w-2))
}
