	cmd.Stdin = os.Stdin
	out, err := cmd.Output()
	if err != nil { return 80, 24 }
	parts := strings.Fields(string(out))
	if len(parts) != 2 { return 80, 24 }
	h, _ := strconv.Atoi(parts[0]); w, _ := strconv.Atoi(parts[1])
	return w, h
}

func getGitStatus() string {
	out, _ := exec.Command("git", "rev-parse", "--abbrev-ref", "HEAD").Output()
